#!/bin/bash
set -euo pipefail
H=/home/hermes/.local/bin/hermes
T=telegram:-1003792973489
G=telegram:-1003114662117
$H cron create '0 9 * * *' --name 'ertalab-standup' --deliver "$G" --failure-deliver "$T" --reasoning-effort low --continuity \
  'Har ish kuni soat 09:00 Asia/Tashkent da Biznes asisstant guruhida muloyim ertalabki standup otkaz. AmoCRM, Airtable, Moizvonki, Telegram, Google Calendar, Google Drive, Gmail, Sheets, Docs, Todoist va Oisha-OS dagi mavjud malumotlarni faqat oqish rejimida tekshir. FAQAT quyidagi tasdiqlangan xodimlar royxatidan foydalan: Baxtiyorjon Gaziyev, Hasanboy Gaziyev, Ahroriy Abdulloh, Beslan, Dilbar, Ifora, Shahnoza Abdijabborova, Rayxona Rahimova, Mumtozmaxal Normurodova. Royxatda yoq shaxsni xodim deb yozma; AmoCRM, Airtable, Telegram yoki Drive dagi mijoz, lid yoki kontakt ismlarini xodim sifatida talqin qilma. Dilnoza Muminova - mijoz (LOZA BY DIOZA), xodim emas. Oldingi run natijasidagi ism va rollarni avtomatik haqiqat deb olma, ularni faqat shu roster bilan solishtir. Har bir xodim uchun bugungi aniq vazifa, deadline, kutilgan natija va mavjud blokerni fakt bilan yoz. Manbasi yoki sanasi yoq malumotni fakt deb yozma. Vazifani xodim nomi bilan individual va muloyim ber. Tashqi tizimlarda hech qanday yozuv ozgartirma.'
$H cron create '0 10 * * 1-6' --name 'ertalab-davomat-10-00' --deliver "$G" --failure-deliver "$T" --reasoning-effort low \
  'Soat 10:00 (Asia/Tashkent) — ish vaqti boshlandi. Jon Branding jamoasi azolaridan ishga kelganliklarini (davomatni) birma-bir muloyim sorab ol. FAQAT quyidagi tasdiqlangan jamoa azolarini alohida punktda birma-bir teg qilib ([Ism](tg://user?id=ID)), ishga kelganini va bugungi birinchi asosiy vazifasini qisqa yozib tasdiqlashini sora: Shahnoza Abdijabborova (8802892610, @jonbranding_assistant), Rayxona Rahimova (8878762085, @RayxonJonbranding), Mumtozmaxal Normurodova (8940413540, @MumtozmaxalJonbranding), Hasanboy Gaziyev (8090679294, @hasan_yahyo), Ifora (5748052638), Ahroriy Abdulloh (1704424936), Beslan (7005708460), Dilbar (8611068511). Faqat ozbek tilida (lotin), samimiy va ruhlantiruvchi ohangda yoz. Royxatda yoq shaxsni xodim deb yozma. Tashqi tizimlarda hech qanday yozuv ozgartirma.'
$H cron create '0 13 * * 1-6' --name 'tushlik-ishtaha' --deliver "$G" --failure-deliver "$T" \
  'Sen Jon Branding jamoasining Telegram guruhiga tushlik vaqtida (13:00) xabar yozasan. Faqat ozbek tilida (lotin), 1-2 qisqa qator: jamoaga samimiy yoqimli ishtaha va maroqli dam olish tila, hamda soat 14:00 da ishga qaytishlarini muloyim eslatib ot. 1-2 mos emoji. Har kuni boshqacha sozla. Boshqa tilda yozma, sarlavha qoshma, faqat tilak va 14:00 eslatmasini qaytar.'
$H cron create '0 14 * * 1-6' --name 'tushlikdan-qaytish-tekshiruvi' --deliver "$G" --failure-deliver "$T" --reasoning-effort low \
  'Soat 14:00 (Asia/Tashkent) boldi, tushlik vaqti tugadi. Jon Branding jamoasidan tushlikdan ishga qaytganliklarini muloyim va samimiy tekshirib ol. FAQAT quyidagi tasdiqlangan jamoa azolarini birma-bir nomma-nom sanab ([Ism](tg://user?id=ID) punktlar bilan) ishga qaytganini va hozir qaysi vazifani davom ettirayotganini qisqa yozib qoyishlarini sora: Shahnoza Abdijabborova (8802892610, @jonbranding_assistant), Rayxona Rahimova (8878762085, @RayxonJonbranding), Mumtozmaxal Normurodova (8940413540, @MumtozmaxalJonbranding), Hasanboy Gaziyev (8090679294, @hasan_yahyo), Ifora (5748052638), Ahroriy Abdulloh (1704424936), Beslan (7005708460), Dilbar (8611068511). Faqat ozbek tilida (lotin), samimiy va dostona ohangda yoz. Royxatda yoq odamni qoshma. Tashqi tizimlarda hech qanday yozuv ozgartirma.'
$H cron create '30 18 * * *' --name 'kunlik-fakt-hisoboti' --deliver "$T" --reasoning-effort low --continuity \
  'Har ish kuni soat 18:30 Asia/Tashkent da Biznes asisstant guruhida kunlik fakt-hisobot ber. AmoCRM, Airtable, Moizvonki, Telegram, Google Calendar, Google Drive, Gmail, Sheets, Docs, Todoist va Oisha-OS ni faqat oqish rejimida solishtir. FAQAT quyidagi tasdiqlangan xodimlar royxatidan foydalan: Baxtiyorjon Gaziyev, Hasanboy Gaziyev, Ahroriy Abdulloh, Beslan, Dilbar, Ifora, Shahnoza Abdijabborova, Rayxona Rahimova, Mumtozmaxal Normurodova. Royxatda yoq shaxsni xodim deb yozma; AmoCRM, Airtable, Telegram yoki Drive dagi mijoz, lid yoki kontakt ismlarini xodim sifatida talqin qilma. Dilnoza Muminova - mijoz (LOZA BY DIOZA), xodim emas. Oldingi run natijasidagi ism va rollarni avtomatik haqiqat deb olma, ularni faqat shu roster bilan solishtir. Har bir xodim nima qilganini faqat kamida bitta manba bilan tasdiqlangan dalil asosida yoz: bajarilgan ish, manba, vaqt va natija. Tasdiqlanmagan ishni bajarildi deb yozma. Har bir tasdiqlangan natija uchun xodimni individual, samimiy va muloyim tabrikla hamda keyingi qadamga motivatsiya ber. Javobsizlik, deadline otishi yoki blokerni muloyim eskalatsiya qil. Hech qanday tashqi tizimda yozuv ozgartirma.'
